<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Random Data Generator','description'=>'Generate random sample names, emails and numbers for testing.','url'=>'https://smarttoolz.in/tools/random-data-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Random Data Generator</h1><p>Generate sample test data instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Rows<input id="n" type="number" min="1" max="50" value="10"></label><button id="go" class="tool-btn">Generate Data</button><textarea id="o" rows="12" readonly></textarea></div></section></main><script>go.onclick=()=>{let N=Math.min(50,Math.max(1,+n.value||10)),names=['Alex','Sam','Jordan','Taylor','Riley'];o.value=Array.from({length:N},(_,i)=>`${i+1},${names[Math.random()*names.length|0]},user${Math.random().toString(36).slice(2,7)}@example.com,${1000+Math.random()*9000|0}`).join('\n')};go.click()</script><?php smarttoolz_tool_page_end(); ?>